WITH with_last AS (SELECT s.*, top1.job_title, top1.level FROM departments s JOIN LATERAL (SELECT c.job_title, c.level FROM employees c WHERE c.dept_id = s.id ORDER BY c.hire_date DESC, c.id DESC LIMIT 1) top1 ON TRUE), enriched AS (SELECT id, dept_name, location, budget, LEAD(budget) OVER (PARTITION BY location, level ORDER BY budget ASC, id ASC) AS next_budget, LAG(budget) OVER (PARTITION BY location, level ORDER BY budget ASC, id ASC) AS prev_budget, ROW_NUMBER() OVER (PARTITION BY location, level ORDER BY budget ASC, id ASC) AS seq_no FROM with_last WHERE job_title NOT IN ('Director', 'Engineer')), deduped AS (SELECT id, dept_name, location, seq_no FROM enriched QUALIFY ROW_NUMBER() OVER (PARTITION BY location ORDER BY seq_no ASC NULLS FIRST, id ASC) = 1), metrics AS (SELECT id, location, MIN(seq_no) OVER w_running AS running_min_seq_no, COUNT(seq_no) OVER w_running AS running_count_seq_no, AVG(seq_no) OVER w_running AS running_avg_seq_no, AVG(seq_no) OVER (PARTITION BY dept_name, location ORDER BY seq_no ASC, id ASC ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS seq_no_avg_5 FROM deduped WINDOW w_running AS (PARTITION BY location, dept_name ORDER BY seq_no ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT location, CASE WHEN running_count_seq_no >= 13 THEN 'PREMIUM' ELSE 'STANDARD' END AS running_count_seq_no_tier, running_count_seq_no, COUNT(CASE WHEN location = 'Bangkok' THEN 1 END) AS bangkok_count, PERCENTILE_APPROX(running_min_seq_no, 0.9) AS running_min_seq_no_p90, COUNT_IF(location = 'Tokyo') AS tokyo_events, MAX(running_count_seq_no) AS max_running_count_seq_no, COUNT(*) FILTER (WHERE location = 'Chiang Mai') AS chiang_mai_rows FROM metrics GROUP BY location, CASE WHEN running_count_seq_no >= 13 THEN 'PREMIUM' ELSE 'STANDARD' END, running_count_seq_no;
